output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file_aisle",
    "text": "A shopper may not push a cart north from the wide aisle mouth into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "N"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "set_down_cart_at_single_file_mouth",
    "text": "When beginning service of a single-file shelf aisle, the cart must be set down at the wide mouth of that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "startCartSetDownAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "startCartSetDownAtMouth",
      "discharge": {
        "not": "hasCart"
      }
    }
  },
  {
    "id": "return_to_cart_after_single_file_pickup",
    "text": "After taking an item inside a single-file shelf aisle, the shopper must return to the cart at the aisle mouth before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "itemPickupInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "itemPickupInSingleFileAisle",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "no_walking_without_cart_except_single_file_excursion",
    "text": "A shopper may walk without the cart only within a single-file aisle excursion area, consisting of the narrow aisle and its mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedNoCartExcursionArea": {
          "or": [
            "singleFileShelfAisle",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedNoCartExcursionArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_put_down_only_at_parking_places",
    "text": "Carts may only be put down at recognized cart parking places, such as the cart bay or a single-file aisle mouth.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartParkingPlace": {
          "or": [
            "cartBay",
            "singleFileAisleMouth"
          ]
        }
      },
      "events": {
        "cartPutDown": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartPutDown",
          {
            "not": "cartParkingPlace"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_interactions_require_cart",
    "text": "Shelf interactions in cart-accessible aisles should be done with the cart present.",
    "abstraction": {
      "state_properties": {
        "cartAccessibleShelfArea": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfArea",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_constricted_exit_lanes",
    "text": "In constricted lower cart lanes, carts should flow toward the exit and not be pushed north or west.",
    "abstraction": {
      "state_properties": {
        "constrictedLowerCartLane": {
          "and": [
            "hasCart",
            {
              "le": [
                "freeWidthV",
                2
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "constrictedLowerCartLane",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  }
]
